//! gRPC module — serves ChatService as a gRPC-Web façade.
//!
//! The ChatService is the primary operator-to-system interface.
//! zeroclaw owns provider/model routing (OD-28); op-web is the thin
//! gRPC façade and tool dispatcher. The chatbot is a delegator with
//! forced tool calling — it never executes backplane operations directly.

use std::sync::Arc;

use tonic::transport::Server;
use tonic_web::GrpcWebLayer;
use tower_http::cors::{Any, CorsLayer};

use op_chat::ChatServiceImpl;
use op_chat::orchestration::proto::op_chat_chat::chat_service_server::ChatServiceServer;

/// Start the gRPC server alongside the HTTP server.
///
/// Serves on the address specified by `GRPC_ADDR` env var,
/// defaulting to `0.0.0.0:50051`.
pub async fn run_grpc_server() -> anyhow::Result<()> {
    let addr = std::env::var("GRPC_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:50051".to_string())
        .parse()
        .map_err(|e| anyhow::anyhow!("Invalid GRPC_ADDR: {e}"))?;

    let chat_service = ChatServiceImpl::new();

    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    tracing::info!("gRPC ChatService listening on http://{}", addr);

    Server::builder()
        .accept_http1(true)
        .layer(GrpcWebLayer::new())
        .layer(cors)
        .add_service(ChatServiceServer::new(chat_service))
        .serve(addr)
        .await
        .map_err(|e| anyhow::anyhow!("gRPC server error: {e}"))
}

