//! gRPC transport stub for ChatService streaming.
//!
//! This is a stub. The actual gRPC client will be wired when ChatService
//! (proto in `crates/op-chat/proto/chat.proto`) is live on the server.
//! For now, `send()` returns a channel that the caller can poll; a future
//! commit replaces the channel with a real tonic streaming response.
//!
//! The shapes here match the proto contract so the view layer can be
//! developed against them without churn.

use anyhow::Result;
use serde::{Deserialize, Serialize};
use tokio::runtime::Handle;
use tokio::sync::mpsc;
use tonic::transport::Channel;

use super::store::ChatMessage;

/// Request to send to ChatService.Send (server-streaming).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SendRequest {
    /// Conversation thread id. Groups episodes.
    pub conversation_id: String,
    /// UI messages in OpenAI-style format (role + content parts).
    pub ui_messages: Vec<serde_json::Value>,
    /// Persona id (e.g. "operator", "analyst", "architect").
    pub persona_id: String,
    /// LLM provider ("anthropic", "openai", "google", "local").
    pub provider: String,
    /// Model name ("claude-sonnet-4-20250514", "gpt-4o", …).
    pub model: String,
}

/// A single frame from the ChatService stream. The view matches on these
/// to render parts, errors, heartbeats, completion, and approval prompts.
#[derive(Debug, Clone)]
pub enum ChatFrame {
    /// A message part (text, tool-call, tool-result, reasoning).
    Part(ChatMessage),
    /// Transport or server error.
    Error(String),
    /// Keepalive — ignore for rendering, but resets idle timeouts.
    Heartbeat,
    /// Stream complete. No more frames will arrive.
    Done,
    /// The assistant wants to call a tool that requires human approval.
    /// The view renders an approval card; the user approves/denies.
    ApprovalRequired {
        tool_call_id: String,
        tool_name: String,
        tool_input: serde_json::Value,
        description: String,
    },
}

/// gRPC transport handle. Holds a tokio runtime handle and a channel.
/// Created once at startup; reused for the lifetime of the app.
pub struct ChatTransport {
    _rt: Handle,
    channel: Channel,
}

impl ChatTransport {
    /// Connect to a ChatService endpoint. The endpoint should be the
    /// tonic-web base URL (e.g. `http://127.0.0.1:11436`).
    pub async fn connect(endpoint: &str) -> Result<Self> {
        let channel = tonic::transport::Endpoint::from_shared(endpoint.to_string())?
            .connect()
            .await?;
        let rt = Handle::try_current()?;
        Ok(Self { _rt: rt, channel })
    }

    /// Send a chat request and return a channel of frames.
    ///
    /// STUB: returns a closed channel immediately. The real implementation
    /// will call `ChatServiceClient::send()` (server-streaming) and forward
    /// decoded frames into the channel.
    pub async fn send(&self, _req: SendRequest) -> Result<mpsc::Receiver<ChatFrame>> {
        let (tx, rx) = mpsc::channel(64);

        // STUB: immediately send Done and close the channel.
        // Real implementation:
        //   let mut client = ChatServiceClient::new(self.channel.clone());
        //   let stream = client.send(req).await?.into_inner();
        //   tokio::spawn(async move {
        //       while let Some(frame) = stream.message().await? {
        //           if tx.send(decode(frame)?).await.is_err() { break; }
        //       }
        //   });
        let _ = self.channel.clone();
        tokio::spawn(async move {
            let _ = tx.send(ChatFrame::Done).await;
        });

        Ok(rx)
    }

    /// Reference to the underlying channel (for future direct use).
    pub fn channel(&self) -> &Channel {
        &self.channel
    }
}

//! egui rendering for the chat panel.
//!
//! Layout:
//! ```text
//! ┌──────────────────────────────┐
//! │  transcript (stick-to-bottom) │
//! │  ┌────────────────────────┐  │
//! │  │ assistant — page surface │  │
//! │  └────────────────────────┘  │
//! │           ┌──────────────┐   │
//! │           │ user — bubble │   │
//! │           └──────────────┘   │
//! │  ▸ tool card (collapsed)     │
//! └──────────────────────────────┘
//! ┌──────────────────────────────┐
//! │  composer (persistent focus)  │
//! │  [textarea]  [Submit]         │
//! │  Thinking...                  │
//! └──────────────────────────────┘
//! ```
//!
//! Identity glyph: a domain-specific operator console mark (the ZeroClaw "Z"
//! glyph), NOT Sparkles, NOT tied to any model.

use super::store::{ChatMessage, ChatStore};
use crate::theme::*;
use egui::{Align, Color32, FontId, Frame, Layout, Margin, RichText, Rounding, Sense, Stroke, Vec2};

/// Main entry point. Renders the full chat panel: transcript + composer.
pub fn render_chat(ui: &mut egui::Ui, store: &mut ChatStore, ctx: &egui::Context) {
    // Throttle repaint to ~60fps during streaming.
    if store.submitted && store.should_repaint() {
        ctx.request_repaint();
    }

    // Layout: transcript fills available space, composer pinned to bottom.
    ui.vertical(|ui| {
        // Transcript takes all available height.
        let available = ui.available_height();
        let composer_h = 88.0_f32;
        let transcript_h = (available - composer_h - 8.0).max(120.0);

        ui.allocate_ui(egui::Vec2::new(ui.available_width(), transcript_h), |ui| {
            render_transcript(ui, store);
        });

        ui.add_space(4.0);

        // Composer pinned to bottom.
        ui.allocate_ui(egui::Vec2::new(ui.available_width(), composer_h), |ui| {
            render_composer(ui, store);
        });
    });
}

/// Sticky-to-bottom scroll area with all messages.
fn render_transcript(ui: &mut egui::Ui, store: &ChatStore) {
    egui::ScrollArea::vertical()
        .id_source("chat-transcript")
        .stick_to_bottom(true)
        .auto_shrink([false; 2])
        .show(ui, |ui| {
            if store.messages.is_empty() {
                render_empty_state(ui);
                return;
            }
            for msg in &store.messages {
                render_message(ui, msg);
            }
        });
}

/// Empty state — identity glyph + hint text.
fn render_empty_state(ui: &mut egui::Ui) {
    ui.add_space(60.0);
    ui.vertical_centered(|ui| {
        // Identity glyph: ZeroClaw "Z", NOT Sparkles.
        let (rect, _) = ui.allocate_exact_size(Vec2::new(40.0, 40.0), Sense::hover());
        ui.painter().rect_filled(rect, Rounding::same(8.0), PRIMARY.linear_multiply(0.15));
        ui.painter().rect_stroke(rect, Rounding::same(8.0), Stroke::new(1.0, PRIMARY.linear_multiply(0.5)));
        ui.painter().text(
            rect.center(),
            egui::Align2::CENTER_CENTER,
            "Z",
            FontId::proportional(20.0),
            PRIMARY,
        );
        ui.add_space(12.0);
        ui.label(RichText::new("ZeroClaw Chat").size(15.0).strong().color(FG));
        ui.add_space(4.0);
        ui.label(
            RichText::new("The chatbot plans, suggests, and delegates — it does not execute.")
                .color(MUTED)
                .size(12.0),
        );
        ui.add_space(2.0);
        ui.label(
            RichText::new("Ask it to orchestrate a task, analyze state, or coordinate agents.")
                .color(MUTED)
                .size(12.0),
        );
    });
}

/// Render a single message, role-styled.
///
/// - assistant: on page surface (no bubble), full width
/// - user: high-contrast bubble, right-aligned
/// - tool: collapsed card with domain icon
/// - system: muted, centered, italic
fn render_message(ui: &mut egui::Ui, msg: &ChatMessage) {
    match msg.role.as_str() {
        "user" => render_user_message(ui, msg),
        "assistant" => render_assistant_message(ui, msg),
        "tool" => render_tool_card(ui, msg),
        "system" => render_system_message(ui, msg),
        _ => render_unknown(ui, msg),
    }
}

/// Assistant message: on page surface (no bubble), full width.
fn render_assistant_message(ui: &mut egui::Ui, msg: &ChatMessage) {
    ui.horizontal(|ui| {
        // Identity glyph
        let (rect, _) = ui.allocate_exact_size(Vec2::new(20.0, 20.0), Sense::hover());
        ui.painter().rect_filled(rect, Rounding::same(4.0), PRIMARY.linear_multiply(0.15));
        ui.painter().text(
            rect.center(),
            egui::Align2::CENTER_CENTER,
            "Z",
            FontId::proportional(11.0),
            PRIMARY,
        );
        ui.add_space(6.0);

        ui.vertical(|ui| {
            match msg.kind.as_str() {
                "reasoning" => render_reasoning(ui, msg),
                "tool-call" => render_tool_card(ui, msg),
                _ => render_text_content(ui, msg, FG),
            }
        });
    });
    ui.add_space(6.0);
}

/// User message: high-contrast bubble, right-aligned.
fn render_user_message(ui: &mut egui::Ui, msg: &ChatMessage) {
    ui.with_layout(Layout::right_to_left(Align::TOP), |ui| {
        let max_w = (ui.available_width() * 0.75).min(600.0);
        Frame::none()
            .fill(PRIMARY.linear_multiply(0.12))
            .stroke(Stroke::new(1.0, PRIMARY.linear_multiply(0.3)))
            .rounding(Rounding::same(10.0))
            .inner_margin(Margin::same(12.0))
            .show(ui, |ui| {
                ui.set_max_width(max_w);
                render_text_content(ui, msg, FG);
            });
    });
    ui.add_space(6.0);
}

/// System message: muted, centered, italic.
fn render_system_message(ui: &mut egui::Ui, msg: &ChatMessage) {
    ui.horizontal_centered(|ui| {
        ui.add_space(20.0);
        let content = msg
            .payload
            .get("content")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        ui.label(RichText::new(content).color(MUTED).size(11.0).italics());
    });
    ui.add_space(4.0);
}

/// Text content — monospace label for now (egui has no markdown built-in).
fn render_text_content(ui: &mut egui::Ui, msg: &ChatMessage, color: Color32) {
    let content = msg
        .payload
        .get("content")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    if content.is_empty() {
        ui.label(RichText::new("(empty)").color(MUTED).size(12.0).italics());
    } else {
        // Monospace for now; markdown renderer will replace this.
        ui.label(RichText::new(content).color(color).size(13.0).monospace());
    }
}

/// Reasoning block: muted, slightly indented, collapsible.
fn render_reasoning(ui: &mut egui::Ui, msg: &ChatMessage) {
    let content = msg
        .payload
        .get("content")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    ui.collapsing(
        RichText::new("▸ reasoning").color(MUTED).size(11.0).italics(),
        |ui| {
            ui.label(RichText::new(content).color(MUTED).size(12.0).monospace());
            // Plan items if present
            if let Some(plan) = msg.payload.get("plan").and_then(|v| v.as_array()) {
                ui.add_space(4.0);
                for (i, step) in plan.iter().enumerate() {
                    let text = step.as_str().unwrap_or("");
                    ui.label(
                        RichText::new(format!("  {}. {}", i + 1, text))
                            .color(MUTED)
                            .size(11.0)
                            .monospace(),
                    );
                }
            }
        },
    );
}

/// Tool card: collapsed by default, domain icon, status indicator.
///
/// Renders for both `"tool"` role (tool-result) and assistant `"tool-call"`
/// kind. When `role == "tool"`, shows output; when `kind == "tool-call"`,
/// shows input.
fn render_tool_card(ui: &mut egui::Ui, msg: &ChatMessage) {
    let is_result = msg.role == "tool" || msg.kind == "tool-result";
    let tool_name = msg
        .payload
        .get("tool")
        .and_then(|v| v.as_str())
        .unwrap_or("tool");
    let status = if is_result {
        msg.payload
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("ok")
    } else {
        "pending"
    };

    let (icon_color, status_glyph) = match status {
        "ok" => (OK, "✓"),
        "error" => (DANGER, "✗"),
        "pending" => (WARN, "…"),
        _ => (MUTED, "•"),
    };

    Frame::none()
        .fill(SURFACE)
        .stroke(Stroke::new(1.0, BORDER))
        .rounding(Rounding::same(6.0))
        .inner_margin(Margin::same(10.0))
        .show(ui, |ui| {
            ui.horizontal(|ui| {
                // Domain icon (not Sparkles — a tool glyph)
                let (rect, _) = ui.allocate_exact_size(Vec2::new(18.0, 18.0), Sense::hover());
                ui.painter()
                    .rect_filled(rect, Rounding::same(4.0), icon_color.linear_multiply(0.15));
                ui.painter().text(
                    rect.center(),
                    egui::Align2::CENTER_CENTER,
                    "⚙",
                    FontId::proportional(10.0),
                    icon_color,
                );

                ui.add_space(6.0);
                ui.label(
                    RichText::new(tool_name)
                        .color(FG)
                        .size(12.0)
                        .strong()
                        .monospace(),
                );

                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    ui.label(
                        RichText::new(status_glyph)
                            .color(icon_color)
                            .size(12.0)
                            .monospace(),
                    );
                });
            });

            // Collapsible detail
            ui.add_space(2.0);
            ui.collapsing(
                RichText::new(if is_result { "output" } else { "input" })
                    .color(MUTED)
                    .size(10.0),
                |ui| {
                    if is_result {
                        let output = msg.payload.get("output").cloned().unwrap_or(serde_json::Value::Null);
                        let pretty = serde_json::to_string_pretty(&output).unwrap_or_default();
                        ui.label(RichText::new(pretty).color(MUTED).size(11.0).monospace());
                    } else {
                        let input = msg.payload.get("input").cloned().unwrap_or(serde_json::Value::Null);
                        let pretty = serde_json::to_string_pretty(&input).unwrap_or_default();
                        ui.label(RichText::new(pretty).color(MUTED).size(11.0).monospace());
                    }
                },
            );
        });
    ui.add_space(4.0);
}

/// Fallback for unknown roles.
fn render_unknown(ui: &mut egui::Ui, msg: &ChatMessage) {
    ui.label(
        RichText::new(format!("[unknown role: {}] {}", msg.role, msg.kind))
            .color(WARN)
            .size(11.0)
            .monospace(),
    );
}

/// Composer: persistent focus, "Thinking…" indicator when submitted,
/// status-aware submit.
fn render_composer(ui: &mut egui::Ui, store: &mut ChatStore) {
    // We need a persistent text buffer. Since ChatStore doesn't hold one
    // (it's append-only messages), we use a static via egui's data store.
    // This is the egui-idiomatic way to persist widget state without
    // adding fields to the app struct.
    let draft_id = egui::Id::new("chat-composer-draft");
    let draft = ui.data_mut(|data| {
        data.get_temp_mut_or_insert_with::<String>(draft_id, || String::new())
            .clone()
    });
    let mut draft = draft;

    Frame::none()
        .fill(SURFACE)
        .stroke(Stroke::new(1.0, BORDER))
        .rounding(Rounding::same(8.0))
        .inner_margin(Margin::same(12.0))
        .show(ui, |ui| {
            ui.horizontal(|ui| {
                // Text area — takes available width
                let resp = ui.add_sized(
                    [ui.available_width() - 100.0, 48.0],
                    egui::TextEdit::multiline(&mut draft)
                        .desired_width(f32::INFINITY)
                        .hint_text("›  message the operator…")
                        .frame(false),
                );

                // Persist the draft
                ui.data_mut(|data| {
                    data.insert_temp(draft_id, draft.clone());
                });

                // Submit button (status-aware)
                let can_submit = !store.submitted && !draft.trim().is_empty();
                let btn_label = if store.submitted {
                    "Cancel"
                } else {
                    "Send"
                };
                let btn = egui::Button::new(
                    RichText::new(btn_label)
                        .color(Color32::WHITE)
                        .size(13.0)
                        .strong(),
                )
                .fill(if can_submit || store.submitted {
                    PRIMARY
                } else {
                    PRIMARY.linear_multiply(0.4)
                })
                .stroke(Stroke::new(1.0, PRIMARY))
                .rounding(Rounding::same(6.0))
                .min_size(Vec2::new(80.0, 48.0));

                if ui.add_enabled(can_submit || store.submitted, btn).clicked() {
                    if store.submitted {
                        // Cancel
                        store.submitted = false;
                    } else if !draft.trim().is_empty() {
                        store.append_user_text(draft.trim());
                        store.submitted = true;
                        draft.clear();
                        ui.data_mut(|data| {
                            data.insert_temp(draft_id, String::new());
                        });
                    }
                }

                // Enter to submit (Shift+Enter for newline)
                if resp.lost_focus()
                    && ui.input(|i| i.key_pressed(egui::Key::Enter))
                    && !store.submitted
                    && !draft.trim().is_empty()
                {
                    store.append_user_text(draft.trim());
                    store.submitted = true;
                    draft.clear();
                    ui.data_mut(|data| {
                        data.insert_temp(draft_id, String::new());
                    });
                    resp.request_focus();
                }
            });

            // Thinking indicator
            if store.submitted {
                ui.add_space(2.0);
                render_thinking(ui);
            }
        });
}

/// Shimmer / thinking indicator. Uses a pulsing dot animation driven by
/// the current time.
fn render_thinking(ui: &mut egui::Ui) {
    ui.horizontal(|ui| {
        let t = ui.input(|i| i.time);
        // Three dots with phase-shifted opacity for a shimmer effect.
        for i in 0..3 {
            let phase = (t * 2.0 + i as f64 * 0.4) % 2.0;
            let alpha = ((phase.sin() + 1.0) * 0.5) as f32;
            let color = PRIMARY.gamma_multiply(alpha * 0.6 + 0.2);
            let (rect, _) = ui.allocate_exact_size(Vec2::new(6.0, 6.0), Sense::hover());
            ui.painter().circle_filled(rect.center(), 3.0, color);
            ui.add_space(2.0);
        }
        ui.add_space(4.0);
        ui.label(
            RichText::new("Thinking…")
                .color(MUTED)
                .size(11.0)
                .italics(),
        );
    });
}

//! Append-only conversation store with imperative writes.
//!
//! This is NOT React-style state. There are no notifications, no re-render
//! triggers, no subscribers. The egui frame loop polls `should_repaint()`
//! each frame and the view reads the `Vec<ChatMessage>` directly.
//!
//! `parking_lot::RwLock` is intentionally avoided here: the store is owned
//! by `ExplorerState` which is already behind a single `&mut` in the egui
//! update loop. A plain `Vec` is correct and zero-overhead. If a future
//! background task needs to push messages, wrap the whole `ChatStore` in a
//! `parking_lot::Mutex` at the call site — do not add interior mutability
//! here.

use serde::{Deserialize, Serialize};
use std::time::Instant;

/// A single chat message part. One logical "turn" may produce several parts
/// (e.g. an assistant reasoning part, then a tool-call part, then a text
/// part). The `kind` discriminator drives the renderer.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChatMessage {
    /// Stable unique id (uuid or nanoid from the server).
    pub id: String,
    /// `"user"` | `"assistant"` | `"tool"` | `"system"`.
    pub role: String,
    /// `"text"` | `"tool-call"` | `"tool-result"` | `"reasoning"`.
    pub kind: String,
    /// Free-form JSON payload — shape depends on `kind`.
    ///
    /// - `text`:      `{ "content": "…" }`
    /// - `tool-call`: `{ "tool": "name", "input": {…}, "tool_call_id": "…" }`
    /// - `tool-result`: `{ "tool_call_id": "…", "output": {…}, "status": "ok"|"error" }`
    /// - `reasoning`: `{ "content": "…", "plan": […] }`
    pub payload: serde_json::Value,
    /// Unix epoch milliseconds.
    pub timestamp: u64,
}

/// Append-only conversation store. Owned by `ExplorerState`.
#[derive(Debug, Clone)]
pub struct ChatStore {
    /// All message parts for the current conversation, in arrival order.
    pub messages: Vec<ChatMessage>,
    /// Conversation thread id. Groups episodes. New conversation = new id.
    pub conversation_id: String,
    /// True while we are waiting for the assistant to respond. Drives the
    /// "Thinking…" indicator and disables the submit button.
    pub submitted: bool,
    /// Last time the view requested a repaint. Used by `should_repaint()`
    /// to throttle to ~60fps.
    pub last_repaint: Instant,
}

impl Default for ChatStore {
    fn default() -> Self {
        Self {
            messages: Vec::new(),
            conversation_id: new_conversation_id(),
            submitted: false,
            last_repaint: Instant::now(),
        }
    }
}

impl ChatStore {
    /// Imperative append. No notification, no callback. The view will pick
    /// this up on the next frame poll.
    pub fn append_part(&mut self, msg: ChatMessage) {
        self.messages.push(msg);
    }

    /// Returns true if more than 16ms have elapsed since the last repaint
    /// request, and updates `last_repaint`. The view calls this each frame
    /// and calls `ctx.request_repaint()` when it returns true during a
    /// streaming response.
    pub fn should_repaint(&mut self) -> bool {
        let elapsed = self.last_repaint.elapsed();
        if elapsed.as_millis() >= 16 {
            self.last_repaint = Instant::now();
            true
        } else {
            false
        }
    }

    /// Reset for a new conversation. Generates a fresh conversation_id and
    /// clears all messages. Called by the "New Chat" button.
    pub fn clear(&mut self) {
        self.messages.clear();
        self.conversation_id = new_conversation_id();
        self.submitted = false;
        self.last_repaint = Instant::now();
    }

    /// Convenience: append a user text message.
    pub fn append_user_text(&mut self, content: impl Into<String>) {
        let content = content.into();
        self.append_part(ChatMessage {
            id: nanoid(),
            role: "user".into(),
            kind: "text".into(),
            payload: serde_json::json!({ "content": content }),
            timestamp: now_ms(),
        });
    }

    /// Convenience: append an assistant text message.
    pub fn append_assistant_text(&mut self, content: impl Into<String>) {
        let content = content.into();
        self.append_part(ChatMessage {
            id: nanoid(),
            role: "assistant".into(),
            kind: "text".into(),
            payload: serde_json::json!({ "content": content }),
            timestamp: now_ms(),
        });
    }
}

// ------------------------------------------------------------------
// ID generation — simple, no external dep. Good enough for the client
// store; the server assigns canonical uuids.
// ------------------------------------------------------------------

fn new_conversation_id() -> String {
    format!("conv_{}", nanoid())
}

fn nanoid() -> String {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(1);
    let n = COUNTER.fetch_add(1, Ordering::Relaxed);
    let ts = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    format!("{:x}{:x}", ts, n)
}

fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

